def is_runtime_impacting(path: str) -> bool:
    normalized = "/" + path.lstrip("/")
    lower = normalized.lower()
    if lower.endswith((".plist", ".service", ".timer")):
        return True
    return any(pattern.lower() in lower for pattern in RUNTIME_PATTERNS)


def load_packet(path: Path | None) -> dict[str, Any]:
    if path is None:
        return {}
    try:
        data = json.loads(path.read_text())
    except Exception as exc:
        raise RuntimeError(f"failed to read closeout packet {path}: {exc}") from exc
    if not isinstance(data, dict):
        raise RuntimeError(f"closeout packet {path} must be a JSON object")
    return data


def packet_dirty_entries(packet: dict[str, Any]) -> list[dict[str, Any]]:
    entries = packet.get("dirtyState", [])
    if entries is None:
        return []
    if not isinstance(entries, list) or not all(isinstance(entry, dict) for entry in entries):
        raise RuntimeError("packet.dirtyState must be a list of objects")
    return entries


def paths_covered(entry: dict[str, Any]) -> set[str]:
    covered: set[str] = set()
    for bucket in DIRTY_BUCKETS:
        value = entry.get(bucket, [])
        if value is None:
            value = []
        if not isinstance(value, list) or not all(isinstance(item, str) for item in value):
            raise RuntimeError(f"dirtyState.{bucket} must be a list of paths")
        covered.update(value)
    return covered


def validate_dirty_packet(repo: Path, dirty_paths: list[str], packet: dict[str, Any]) -> list[str]:
    if not dirty_paths:
        return []
    repo_str = str(repo)
    entries = [
        entry
        for entry in packet_dirty_entries(packet)
        if entry.get("repo") in {repo_str, str(repo.resolve())}
    ]
    if not entries:
        return [f"{repo}: dirty-state handoff packet required for {len(dirty_paths)} dirty path(s)"]
    errors: list[str] = []
    entry = entries[0]
    covered = paths_covered(entry)
    missing = sorted(set(dirty_paths) - covered)
    if missing:
        errors.append(f"{repo}: dirty-state packet does not classify: {', '.join(missing)}")
    unknown = entry.get("unknown") or []
    if unknown and not entry.get("nextQuestion"):
        errors.append(f"{repo}: unknown dirty paths require nextQuestion")
    required_keys = {"blocksCommit", "nextQuestion"}
    missing_keys = sorted(required_keys - set(entry))
    if missing_keys:
        errors.append(f"{repo}: dirty-state packet missing keys: {', '.join(missing_keys)}")
    errors.extend(validate_residual_actions(repo, entry))
    return errors


def validate_residual_actions(repo: Path, entry: dict[str, Any]) -> list[str]:
    residual_paths: set[str] = set()
    for bucket in RESIDUAL_BUCKETS:
        residual_paths.update(entry.get(bucket) or [])
    if not residual_paths:
        return []
    actions = entry.get("residualActions")
    if not isinstance(actions, list) or not actions:
        return [
            f"{repo}: residual dirty paths require residualActions entries with "
            f"paths/action/rationale/nextStep covering: {', '.join(sorted(residual_paths))}"
        ]
    errors: list[str] = []
    covered: set[str] = set()
    for action in actions:
        if not isinstance(action, dict):
            errors.append(f"{repo}: residualActions entries must be objects")
            continue
        missing_fields = [field for field in RESIDUAL_ACTION_FIELDS if not action.get(field)]
        if missing_fields:
            errors.append(f"{repo}: residualActions entry missing {', '.join(missing_fields)}")
        paths = action.get("paths")
        if isinstance(paths, list):
            covered.update(item for item in paths if isinstance(item, str))
    missing_residual = sorted(residual_paths - covered)
    if missing_residual:
        errors.append(f"{repo}: residualActions does not cover: {', '.join(missing_residual)}")
    return errors


def validate_runtime_packet(runtime_paths: list[str], packet: dict[str, Any]) -> list[str]:
    if not runtime_paths:
        return []
    restart = packet.get("runtimeRestart")
    if not isinstance(restart, dict):
        return ["runtime-impacting paths touched; restart inventory packet required"]
    if restart.get("runtimeImpact") is not True:
        return ["runtimeRestart.runtimeImpact must be true when runtime-impacting paths were touched"]
    affected = restart.get("affectedTargets")
    if not isinstance(affected, list) or not affected:
        return ["runtimeRestart.affectedTargets must name concrete process/service/app/port/session targets"]
    action = restart.get("actionTaken")
    if action not in {"restarted-and-verified", "needs-user-approval", "not-required"}:
        return ["runtimeRestart.actionTaken must be restarted-and-verified, needs-user-approval, or not-required"]
    if action == "restarted-and-verified":
        verification = restart.get("verification")
        if not isinstance(verification, list) or not verification:
            return ["runtimeRestart.verification is required after restart"]
    if action == "needs-user-approval" and not restart.get("remainingQuestion"):
        return ["runtimeRestart.remainingQuestion is required when approval is needed"]
    return []


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Validate agent closeout dirty-state and runtime-restart handoff.")
    parser.add_argument("--repo", action="append", type=Path, default=[], help="Git repo to inspect. Repeatable.")
    parser.add_argument("--touched", action="append", default=[], help="Path touched by this run. Repeatable.")
    parser.add_argument("--packet", type=Path, help="Closeout packet JSON to validate.")
    parser.add_argument("--json", action="store_true", help="Emit JSON.")
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    repos = [repo.resolve() for repo in args.repo]
    packet = load_packet(args.packet)
    repo_reports: list[dict[str, Any]] = []
    actions: list[str] = []
    errors: list[str] = []
    pattern_action_pending = False
    uncovered_dirty = False
    touched_memory = any(path == "memory" or path.startswith("memory/") for path in args.touched)

    for repo in repos:
        dirty_paths = git_dirty_paths(repo)
        report: dict[str, Any] = {"repo": str(repo), "dirtyPaths": dirty_paths}
        covered: set[str] = set()
        if is_dotfiles_memory_repo(repo):
            diag = diagnose_memory_sync(repo, dirty_paths)
            diagnosis = diag["diagnosis"]
            report["closeout"] = diagnosis
            covered = set(diag["coveredPaths"])
            if not diagnosis["ok"]:
                current_task_memory = bool(covered) or touched_memory
                diagnosis["blocksCurrentTask"] = current_task_memory
                if current_task_memory:
                    pattern_action_pending = True
                    action = diagnosis.get("recommendedAction")
                    if action:
                        actions.append(f"{repo}: {diagnosis['state']} — run `{action['command']}` ({action['rationale']})")
                    else:
                        actions.append(f"{repo}: {diagnosis['state']} — {diagnosis['summary']}")
        repo_reports.append(report)
        remaining = [path for path in dirty_paths if path not in covered]
        if remaining:
            uncovered_dirty = True
        errors.extend(validate_dirty_packet(repo, remaining, packet))

    runtime_paths = sorted({path for path in args.touched if is_runtime_impacting(path)})
    errors.extend(validate_runtime_packet(runtime_paths, packet))

    if uncovered_dirty and not packet.get("dirtyState"):
        actions.append("Provide a dirty-state handoff packet classifying every dirty path.")
    if runtime_paths and "runtimeRestart" not in packet:
        actions.append("Provide a runtime restart inventory naming affected targets and verification or approval question.")
    if errors:
        actions.extend(errors)

    ok = not errors and not pattern_action_pending
    result = {
        "ok": ok,
        "dirtyStateRequired": uncovered_dirty,
        "runtimeRestartRequired": bool(runtime_paths),
        "runtimeImpactingPaths": runtime_paths,
        "repos": repo_reports,
        "packet": packet or None,
        "actionsRequired": actions,
    }

    if args.json:
        print(json.dumps(result, indent=2, sort_keys=True))
    else:
        print("agent-closeout-check: " + ("ok" if result["ok"] else "needs closeout action"))
        for report in repo_reports:
            closeout = report.get("closeout")
            if closeout:
                marker = "ok" if closeout["ok"] else ("action" if closeout.get("blocksCurrentTask", True) else "info")
                print(f"- [{marker}] {report['repo']}: memory-sync = {closeout['state']} — {closeout['summary']}")
        for action in actions:
            print(f"- {action}")
    return 0 if result["ok"] else 1


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except RuntimeError as exc:
        print(f"agent-closeout-check: {exc}", file=sys.stderr)
        raise SystemExit(2)
